<span class="line"><span style="--shiki-dark:#CE9178;--shiki-light:#A31515;">    &quot;courier.push.apple.com&quot;</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">, </span><span style="--shiki-dark:#6A9955;--shiki-light:#008000;">// iOS push notifications</span></span>
